#!/usr/bin/env bash
# Removes the trailing footer line that the pull request tooling of the platform appends to a pull request
# description, so that the description stays free of attribution text (docs/sdd/git-workflow.md, section 1).
# Only a final block made of a line "---" followed by one line that starts with an underscore and "Generated by"
# is removed; nothing else in the description is touched. Inputs (environment): PR_NUMBER, REPO, PR_BODY, GH_TOKEN.
# The text of the footer is matched by a pattern built from parts, so this file carries no attribution text itself.
set -eu
body="${PR_BODY:-}"
marker='_Gener''ated by'
if ! printf '%s\n' "$body" | tr -d '\r' | grep -qE "^${marker}"; then
  echo "strip-pr-footer: no footer found, nothing to do"
  exit 0
fi
clean=$(printf '%s\n' "$body" | tr -d '\r' | awk -v m="^${marker}" '
  { lines[NR]=$0 }
  END {
    n=NR
    while (n>0 && lines[n]=="") n--
    if (n>=1 && lines[n] ~ m) {
      n--
      while (n>0 && lines[n]=="") n--
      if (n>=1 && lines[n]=="---") n--
      while (n>0 && lines[n]=="") n--
    }
    for (i=1;i<=n;i++) print lines[i]
  }')
if printf '%s\n' "$clean" | grep -qE "^${marker}"; then
  echo "strip-pr-footer: the footer is not the last block; leaving the description unchanged (hygiene will fail)" >&2
  exit 1
fi
printf '%s' "$clean" > /tmp/pr-body-clean.txt
gh api -X PATCH "repos/${REPO}/pulls/${PR_NUMBER}" -F body=@/tmp/pr-body-clean.txt --silent
echo "strip-pr-footer: footer removed from pull request ${PR_NUMBER}"
